#!/usr/bin/env bun
// Generated by minsky compile. Do not edit directly.
// Source: .minsky/hooks/ask-conversation-map.ts

// Ask -> conversation attribution map (mt#3564).
//
// The shared store behind BOTH halves of the answered-ask injection:
// `stamp-ask-conversation.ts` (PostToolUse on `mcp__minsky__asks_create`) writes an
// entry; `inject-ask-responses.ts` (UserPromptSubmit) reads it to decide which
// answered asks belong to the conversation currently taking a turn.
//
// ## Why a local file and not a database column
//
// The obvious place for "which conversation filed this ask" is the ask row itself,
// and `Ask.parentSessionId` looks like the field for it. It is not: it holds the
// WORKSPACE session id (`src/cockpit/entity-thread-launch.ts` joins it as
// `WHERE minsky_session_id = ...`), it is caller-supplied and never auto-stamped, and
// a MAIN-workspace conversation — the dominant ask-filing case — has no workspace
// session at all, so there is nothing to put in it. The workspace->conversation bridge
// that does exist (`findOpenAskForConversation`) records its own measured coverage as
// 4 of 15 conversations, behind an FK a live conversation cannot yet satisfy.
//
// So the attribution has to be recorded where both ids are visible at once, which is
// the PostToolUse hook (the `stamp-session-creator-link.ts` precedent, mt#3120). Given
// that, a local file beats a new column on two counts:
//
//   - **It keeps the DB out of the hook.** A DB-writing hook needs `reflect-metadata`
//     AND initialized configuration, and fails DIFFERENTLY at each layer; mem#672
//     records `record-subagent-invocation.ts` writing 0 of 62 rows for the table's
//     entire life while three features shipped onto it green. This store needs no
//     bootstrap, so it cannot fail that way.
//   - **The consumer is local anyway.** The injection hook reads a local cache by
//     construction (ADR-028 D7(5) — no unbounded network IO in a dispatcher budget), so
//     a DB column would have to be replicated back down to a file regardless.
//
// The attribution is also intrinsically harness-local: a Claude Code conversation uuid
// means nothing to another machine, so durability beyond this state dir buys nothing.
//
// ## Concurrency
//
// `record()` is read-modify-write with an atomic temp+rename, so a reader never sees a
// torn file. Two `asks_create` calls landing inside the same read-write window would
// lose one entry — accepted deliberately: ask creation runs a few times a day, the loss
// is one notice rather than corruption, and the alternative (an append-only log plus
// compaction) is more machinery than the failure justifies.
//
// @see mt#3564 — this task
// @see .minsky/hooks/stamp-ask-conversation.ts — the writer
// @see .minsky/hooks/inject-ask-responses.ts — the reader
// @see .minsky/hooks/stamp-session-creator-link.ts — the both-ids-visible precedent
// @see mem#672 — why this store deliberately touches no database

import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";

/** Cache filename under the Minsky state dir. */
export const ASK_CONVERSATION_MAP_FILENAME = "ask-conversation-map.json";

/**
 * How long an attribution entry is kept.
 *
 * This constant IS this task's answer to "an ask answered while no conversation is
 * running is not lost" — the retention window is what makes the claim true or false.
 * Seven days, chosen against the originating incident rather than as a round number:
 * ask#6687 was answered ~16h after it was filed, and the asks currently open in the
 * inbox have sat for days. A window shorter than the observed answer latency would
 * drop exactly the slow answers this mechanism exists to deliver.
 *
 * An ask answered after the window still reaches the operator's inbox and the cockpit;
 * what expires is only the in-conversation notice.
 *
 * **Enforced on BOTH paths as of mt#4541.** Until then `pruneEntries` ran only from
 * `recordAskConversation`, so this was a ceiling the store applied when it happened to be
 * written and never otherwise — a machine that stopped filing asks kept entries past the
 * window indefinitely. `readAskConversationMap` now prunes too, which is what lets a
 * downstream consumer treat this number as a real bound rather than an aspiration:
 * `WAKE_PENDING_DELIVERED_RETENTION_MS`
 * (`packages/domain/src/ask/wake-pending-retention.ts`) is derived from it and was set to
 * DOUBLE it purely to cover the gap between declared and enforced.
 */
export const ENTRY_MAX_AGE_MS = 7 * 24 * 60 * 60 * 1000;

/**
 * Hard cap on retained entries, newest-first. A second bound beside the age window so a
 * burst cannot grow the file without limit — the consumer parses it on every turn, and
 * the sibling ask-state cache's own docblock rejects an unbounded ask set for exactly
 * this reason.
 */
export const MAX_ENTRIES = 200;

/** One recorded attribution. */
export interface AskConversationEntry {
  /** Harness conversation uuid (`session_id` on the hook payload). */
  conversationId: string;
  /** `ask#N` short id when the create result carried one — for rendering only. */
  shortId?: string;
  /** ISO-8601 time the entry was recorded. */
  recordedAt: string;
}

/** The on-disk record: ask uuid -> attribution. */
export interface AskConversationMap {
  entries: Record<string, AskConversationEntry>;
}

/** Resolve the Minsky state dir: MINSKY_STATE_DIR, else XDG_STATE_HOME/minsky, else ~/.local/state/minsky. */
function getStateDir(): string {
  const override = process.env["MINSKY_STATE_DIR"];
  if (override) return override;
  const xdgStateHome =
    process.env["XDG_STATE_HOME"] || path.join(process.env["HOME"] || os.homedir(), ".local/state");
  return path.join(xdgStateHome, "minsky");
}

/** Absolute path to the attribution map. */
export function getAskConversationMapPath(): string {
  return path.join(getStateDir(), ASK_CONVERSATION_MAP_FILENAME);
}

/**
 * Coerce an arbitrary parsed value into a map. Tolerant of every malformed shape the
 * file can take — it is machine-written but lives in a user-writable state dir, and a
 * parse failure here must degrade to "no attributions known", never throw into a hook.
 */
export function coerceMap(parsed: unknown): AskConversationMap {
  if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) return { entries: {} };
  const rawEntries = (parsed as { entries?: unknown }).entries;
  if (!rawEntries || typeof rawEntries !== "object" || Array.isArray(rawEntries)) {
    return { entries: {} };
  }
  const entries: Record<string, AskConversationEntry> = {};
  for (const [askId, value] of Object.entries(rawEntries as Record<string, unknown>)) {
    if (!value || typeof value !== "object" || Array.isArray(value)) continue;
    const { conversationId, shortId, recordedAt } = value as Record<string, unknown>;
    if (typeof conversationId !== "string" || conversationId.length === 0) continue;
    if (typeof recordedAt !== "string" || recordedAt.length === 0) continue;
    entries[askId] = {
      conversationId,
      recordedAt,
      ...(typeof shortId === "string" && shortId.length > 0 ? { shortId } : {}),
    };
  }
  return { entries };
}

/**
 * Drop entries older than {@link ENTRY_MAX_AGE_MS}, then keep the newest
 * {@link MAX_ENTRIES}. Pure over its inputs so the retention policy unit-tests without
 * a filesystem or a clock.
 *
 * An entry whose `recordedAt` does not parse is dropped rather than kept: it cannot be
 * aged out later either, so keeping it would make it permanent.
 */
export function pruneEntries(
  entries: Record<string, AskConversationEntry>,
  nowMs: number,
  maxAgeMs: number = ENTRY_MAX_AGE_MS,
  maxEntries: number = MAX_ENTRIES
): Record<string, AskConversationEntry> {
  const dated: Array<[string, AskConversationEntry, number]> = [];
  for (const [askId, entry] of Object.entries(entries)) {
    const recordedMs = Date.parse(entry.recordedAt);
    if (Number.isNaN(recordedMs)) continue;
    if (nowMs - recordedMs > maxAgeMs) continue;
    dated.push([askId, entry, recordedMs]);
  }
  // Sort ONLY when the cap actually binds (PR #3321 R1). The age filter above is O(N);
  // the sort is O(N log N) and exists solely to decide WHICH entries survive `maxEntries`.
  // When the surviving set already fits, every order produces the same result, so the
  // sort is pure waste — and since mt#4541 this runs on the READ path, i.e. on every
  // UserPromptSubmit, where the dispatcher budget is real (ADR-028 D7(5)).
  if (dated.length > maxEntries) dated.sort((a, b) => b[2] - a[2]);
  const kept: Record<string, AskConversationEntry> = {};
  for (const [askId, entry] of dated.slice(0, maxEntries)) kept[askId] = entry;
  return kept;
}

/**
 * Read the map, dropping entries the retention policy has expired. Returns an empty map
 * when the file is absent or unreadable — both mean "no attributions known", which is
 * also the ordinary state on a fresh machine.
 *
 * ## Why the prune is here and not only in `recordAskConversation` (mt#4541)
 *
 * {@link ENTRY_MAX_AGE_MS} was a NOMINAL ceiling until this change: `pruneEntries` ran
 * only from the WRITE path, so the window bounded a machine that keeps filing asks and
 * bounded nothing on one that stops. An entry on a quiet machine outlived its declared
 * window indefinitely, and the read path returned it as though it were live.
 *
 * Pruning at the READ is what makes the declared window the enforced one, and this is
 * the layer that closes the whole class rather than one accessor. The consumer
 * (`inject-ask-responses.ts`) uses the returned map THREE ways — `askIdsForConversation`,
 * a `shortId` lookup, and the watermark prune that deletes keys the map no longer knows
 * about. Filtering inside `askIdsForConversation` alone would fix the first and leave the
 * third reading unfiltered `entries`, so an expired ask's watermark key would never age
 * out. One filter here, and all three inherit it.
 *
 * `nowMs` is injected rather than read from the clock at each call site so the retention
 * behaviour stays deterministic under test — the same convention {@link pruneEntries} and
 * {@link recordAskConversation} already use. Production passes nothing.
 */
export function readAskConversationMap(
  mapPath: string = getAskConversationMapPath(),
  nowMs: number = Date.now()
): AskConversationMap {
  try {
    if (!fs.existsSync(mapPath)) return { entries: {} };
    const parsed = coerceMap(JSON.parse(String(fs.readFileSync(mapPath, "utf-8"))));
    return { entries: pruneEntries(parsed.entries, nowMs) };
  } catch {
    // intentional-swallow: an unreadable attribution map degrades to "no attributions",
    // which is this store's documented fail-open posture. A hook must never throw here.
    return { entries: {} };
  }
}

/**
 * Record one attribution, pruning as a side effect. Returns true when the write landed.
 *
 * `nowIso` is injected rather than read from the clock so the retention behaviour is
 * deterministic under test.
 */
export function recordAskConversation(
  askId: string,
  entry: AskConversationEntry,
  nowIso: string,
  mapPath: string = getAskConversationMapPath()
): boolean {
  try {
    // One clock for both prunes (mt#4541): the read now prunes too, and passing the
    // caller's instant keeps the whole read-modify-write on the injected clock rather
    // than mixing it with `Date.now()` halfway through.
    const nowMs = Date.parse(nowIso) || Date.now();
    const current = readAskConversationMap(mapPath, nowMs);
    const merged = { ...current.entries, [askId]: entry };
    // Still pruned here, and not redundantly: the read pruned what was ON DISK, this
    // applies MAX_ENTRIES to the set with the new entry merged in.
    const record: AskConversationMap = {
      entries: pruneEntries(merged, nowMs),
    };
    fs.mkdirSync(path.dirname(mapPath), { recursive: true });
    // Atomic temp+rename: a torn file would parse as a plausible map with some
    // attributions missing, which the consumer cannot distinguish from "never stamped".
    const tempPath = `${mapPath}.tmp-${process.pid}`;
    fs.writeFileSync(tempPath, `${JSON.stringify(record, null, 2)}\n`, "utf-8");
    fs.renameSync(tempPath, mapPath);
    return true;
  } catch {
    // intentional-swallow: attribution is best-effort. A failed stamp costs one
    // un-delivered notice; throwing would fail the tool call the hook is observing.
    return false;
  }
}

/**
 * Ask ids currently attributed to `conversationId`. The consumer's filter, and the
 * reason the map is keyed by ask id rather than by conversation: the producer needs the
 * full id set (below) and the consumer needs one conversation's slice, so neither
 * direction is free — this keeps the file shape matching the ask-state cache it joins
 * against.
 */
export function askIdsForConversation(map: AskConversationMap, conversationId: string): string[] {
  return Object.entries(map.entries)
    .filter(([, entry]) => entry.conversationId === conversationId)
    .map(([askId]) => askId);
}

/** Every attributed ask id — the producer's input, across all conversations. */
export function allAttributedAskIds(map: AskConversationMap): string[] {
  return Object.keys(map.entries);
}
